<?php
require_once __DIR__.'/includes/bootstrap.php';
require_once __DIR__.'/includes/portal-auth.php';
if(isset($_GET['logout'])) portal_logout('index.php?portal=inicio');
$ctx=portal_context();
if(!$ctx){$error=portal_handle_login('index.php?portal=inicio');portal_login_page('home',$error);}
$allowed=portal_allowed_campaigns($ctx);
$roll=portal_campaign_rollup($allowed);
$rows=$roll['rows'];
$recent=array_slice($rows,0,4);
$best=null;
foreach($rows as $r){
    if(($r['metrics']['sent']??0)<=0) continue;
    if(!$best || ($r['metrics']['open_rate']??0)>($best['metrics']['open_rate']??0))$best=$r;
}
$sentPct=$roll['campaigns']?round($roll['sent_campaigns']/$roll['campaigns']*100,1):0;
